/**
 * Build-time data access (getStaticProps / getStaticPaths only).
 * Reads the snapshot generated by etl/build_snapshot.py.
 */
import fs from "fs"
import path from "path"
import zlib from "zlib"

const ROOT = path.join(process.cwd(), "..", "snapshot")
const PUBLIC_DATA = path.join(process.cwd(), "public", "data")
const cache = {}

function readJson(file) {
    if (!(file in cache)) {
        cache[file] = JSON.parse(fs.readFileSync(file, "utf-8"))
    }
    return cache[file]
}

export const snapshot = (rel) => readJson(path.join(ROOT, rel))
export const publicData = (rel) => readJson(path.join(PUBLIC_DATA, rel))
export const snapshotText = (rel) => fs.readFileSync(path.join(ROOT, rel), "utf-8")

export const getMeta = () => snapshot("meta.json")

// ------------------------------------------------------------- CMS

const isPublished = (a) => !a?.attributes?.preview

export const getArticles = ({ includePreview = false } = {}) =>
    snapshot("cms/articles.json").filter((a) => includePreview || isPublished(a))

export const getArticleBySlug = (slug) => getArticles().find((a) => a.attributes.slug === slug) || null

export function getCategories() {
    // Strapi returned category articles including preview ones; filter them like the pages did.
    return snapshot("cms/categories.json").map((c) => ({
        ...c,
        attributes: {
            ...c.attributes,
            articles: { data: c.attributes.articles.data.filter(isPublished) },
        },
    }))
}

/** Categories without populated articles (= Strapi /categories without populate) */
export const getCategoriesPlain = () =>
    snapshot("cms/categories.json").map((c) => {
        const { articles, ...attributes } = c.attributes
        return { id: c.id, attributes }
    })

export const getLanding = () => snapshot("cms/landing.json")
export const getCharts = () => snapshot("cms/charts.json")
export const getChartBySlug = (slug) => getCharts().find((c) => c.attributes.slug === slug) || null

export const hasCategory = (article, name) =>
    (article.attributes.categories?.data || []).some((c) => c.attributes.Category === name)

// ------------------------------------------------------------- contracts

const bucketName = (s) => String(s).toLowerCase().replace(/[^A-Za-z0-9_.\-]/g, (c) => "~" + c.charCodeAt(0).toString(16).toUpperCase().padStart(2, "0"))

export function getContractMeta(address) {
    const file = path.join(PUBLIC_DATA, "contracts", "meta", `${bucketName(String(address).slice(3, 5))}.json.gz`)
    if (!(file in cache)) {
        if (!fs.existsSync(file)) return null
        cache[file] = JSON.parse(zlib.gunzipSync(fs.readFileSync(file)).toString("utf-8"))
    }
    return cache[file][address] || null
}

export const getTopContracts = () => snapshot("contracts/top_14d.json")
export const getPrerenderedContracts = () => snapshot("contracts/prerender.json")

// ------------------------------------------------------------- datasets / blocks

export const getDataBlocks = () => snapshot("data_blocks/all.json")
export const getGeneralDatasets = () => snapshot("datasets/general.json")
export const getEntrypointDatasets = () => snapshot("datasets/entrypoints.json")
export const getEntrypointNames = () => Object.keys(getEntrypointDatasets()).sort()

export function getDatasetMeta(identifier) {
    const file = path.join(PUBLIC_DATA, "datasets", "by-id", `${bucketName(identifier)}.json`)
    return fs.existsSync(file) ? (readJson(file)[identifier] || null) : null
}

export const getPrerenderedEntrypoints = () => snapshot("entrypoints/prerender.json")
